Simple WorkerThread PoolRound-Robin PoolPeriodic Worker <pre><code>#include "siddiqsoft/simple_worker.hpp"
#include &lt;iostream&gt;
#include &lt;chrono&gt;

struct MyTask {
    std::string data;
    void operator()() { 
        std::cout &lt;&lt; "Processing: " &lt;&lt; data &lt;&lt; std::endl;
    }
};

int main() {
    siddiqsoft::simple_worker&lt;MyTask&gt; worker{[](auto&amp; task) {
        task();  // Execute the task
    }};

    // Queue work items
    for (int i = 0; i &lt; 100; ++i) {
        worker.queue(MyTask{"data-" + std::to_string(i)});
    }

    std::this_thread::sleep_for(std::chrono::seconds(1));
    return 0;
}
</code></pre> <pre><code>#include "siddiqsoft/simple_pool.hpp"
#include &lt;iostream&gt;
#include &lt;chrono&gt;

struct MyTask {
    std::string data;
    void operator()() { 
        std::cout &lt;&lt; "Thread " &lt;&lt; std::this_thread::get_id()
                  &lt;&lt; " processing " &lt;&lt; data &lt;&lt; std::endl;
    }
};

int main() {
    // Pool of worker threads sharing a single queue
    siddiqsoft::simple_pool&lt;MyTask&gt; pool{[](auto&amp; task) {
        task();  // Execute task
    }};

    for (int i = 0; i &lt; 1000; ++i) {
        pool.queue(MyTask{"item-" + std::to_string(i)});
    }

    std::this_thread::sleep_for(std::chrono::seconds(2));
    return 0;
}
</code></pre> <pre><code>#include "siddiqsoft/roundrobin_pool.hpp"
#include &lt;iostream&gt;
#include &lt;chrono&gt;

struct MyTask {
    std::string data;
    void operator()() { 
        std::cout &lt;&lt; "Round-robin item: " &lt;&lt; data &lt;&lt; std::endl;
    }
};

int main() {
    // Multi-threaded pool with per-thread queues
    siddiqsoft::roundrobin_pool&lt;MyTask&gt; pool{[](auto&amp; task) {
        task();
    }};

    for (int i = 0; i &lt; 1000; ++i) {
        pool.queue(MyTask{"item-" + std::to_string(i)});
    }

    std::this_thread::sleep_for(std::chrono::seconds(2));
    return 0;
}
</code></pre> <pre><code>#include "siddiqsoft/periodic_worker.hpp"
#include &lt;iostream&gt;
#include &lt;chrono&gt;

int main() {
    // Execute callback every 500ms
    siddiqsoft::periodic_worker&lt;&gt; timer{
        []() {
            std::cout &lt;&lt; "Tick!" &lt;&lt; std::endl;
        },
        std::chrono::milliseconds(500)
    };

    std::this_thread::sleep_for(std::chrono::seconds(5));
    return 0;
}
